  for (const [name, seconds, extra] of spec.beats(staged)) { beats[name] = { from: length, to: length + seconds, ...extra }; length += seconds; }
  const duration = length;
  const names = Object.keys(beats);
  const beatAt = (t) => names.find((name) => t < beats[name].to) ?? names[names.length - 1];
  const timeline = A.createTimeline({ autoplay: false, defaults: { ease: "linear" } });
  const tools = { root, scope, on, put, clamp, smooth, token, beats, duration, STAGES, staged, drawHeat, drawFlows, drawLamps, drawBuild, drawClad, drawCallouts, drawCut, drawCamera, HOME, unpin, hide };
  // ramp(beat, { at, for, ease }) -> { v }: a value that goes 0 -> 1 inside a beat. `at` is seconds from the beat's start, or back
  // from its end when negative; it lasts `for` seconds, by default to the end of the beat. `count` and `stagger` (ms) give a row of them.
  // Every ramp is its own target with one tween. That is deliberate: anime.js 4.5 does not restore a value that several tweens of
  // one timeline share when it seeks backward (the value keeps what a later tween left), and seek(t) must not depend on the past.
