      if (start < clear - 1e-6) throw new Error("camera: the move at " + start.toFixed(2) + " s starts before the last one has ended");
      if (to && to.zoom > 1.8) throw new Error("camera: zoom " + to.zoom + " is too close");
      clear = start + seconds;
